CREATE TABLE IF NOT EXISTS curriculum_themes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),class_level text NOT NULL,subject_name text NOT NULL,name text NOT NULL,sort_order integer NOT NULL DEFAULT 0,curriculum_version text,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','REVIEWED','LIVE','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(class_level,subject_name,name));
CREATE TABLE IF NOT EXISTS curriculum_theme_topics (theme_id uuid NOT NULL REFERENCES curriculum_themes(id) ON DELETE CASCADE,topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE,sort_order integer NOT NULL DEFAULT 0,PRIMARY KEY(theme_id,topic_id));
CREATE INDEX IF NOT EXISTS curriculum_theme_live_idx ON curriculum_themes(class_level,subject_name,status,sort_order);